package com.example.transactionrecovery.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import static com.example.transactionrecovery.domain.States.OutboxStatus;
@Entity @Table(name="outbox_event") public class OutboxEvent { @Id public UUID id; @Column(nullable=false) public String tenantId; @Column(nullable=false) public String eventType; @Column(nullable=false,length=2000) public String payload; @Enumerated(EnumType.STRING) @Column(nullable=false) public OutboxStatus status; @Column(nullable=false) public int publishAttempts; @Column(nullable=false) public Instant occurredAt; protected OutboxEvent(){} public OutboxEvent(UUID id,String tenant,String type,String payload){this.id=id;tenantId=tenant;eventType=type;this.payload=payload;status=OutboxStatus.PENDING;occurredAt=Instant.now();} }
